import { p5Source } from "../p5Source";

function stripDescribe(code: string): string {
  return code
    .replace(/describe\s*\(\s*(["'])((?:(?!\1).)*)\1\s*\)\s*;?\s*/g, "")
    .trim();
}

function wrapSketch(code: string): string {
  const hasSetup = /function\s+setup\s*\(/.test(code);
  if (!hasSetup) {
    return `function setup() {\n${code.split("\n").map((l) => "  " + l).join("\n")}\n}`;
  }
  return code;
}

export function getFullscreenPreviewHtml(code: string, colorScheme?: "light" | "dark"): string {
  const isDark = colorScheme === "dark";
  const sketch = wrapSketch(stripDescribe(code ?? ""));
  const bodyBg = isDark ? "#000000" : "#111111";

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover">
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body {
    width: 100%;
    height: 100%;
    background: ${bodyBg};
    overflow: hidden;
  }
  #sketch {
    position: fixed;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  #sketch canvas { display: block; }
  #error {
    color: #FF5252;
    font-family: monospace;
    font-size: 14px;
    padding: 24px;
    text-align: center;
    white-space: pre-wrap;
  }
</style>
</head>
<body>
<div id="sketch"></div>
<script>${p5Source.replace(/<\/script>/gi, "<\\/script>")}</script>
<script>
(function() {
  var container = document.getElementById('sketch');
  try {
    container.__p5 = new p5(function(p) {
      var src = ${JSON.stringify(sketch)};
      var run = new Function('p', src + ';return { setup: typeof p.setup === "function" ? p.setup : null, draw: typeof p.draw === "function" ? p.draw : null };');
      var fns = run(p);
      p.setup = fns.setup || function() {};
      p.draw = fns.draw;
    }, container);
  } catch (e) {
    container.innerHTML = '<div id="error">' + (e && e.message ? e.message : String(e)) + '</div>';
  }
})();
</script>
</body>
</html>`;
}

parts.text:
Hmm, wait. My wrapSketch with `new Function('p', ...)` approach is overly complex and possibly buggy. The issue: p5 global mode vs instance mode. When we do `new p5(fn, container)` with a function that has `p.setup`, `p.draw`, etc., that's instance mode. But the user's code uses global mode functions (`function setup()`, `function draw()`, calls like `background(20)` without `p.`). If we run it via `new Function('p', ...)`, the `setup`/`draw` definitions would be inside the function scope and wouldn't have access to `p.` prefixed calls. Global p5 functions (background, fill, createCanvas) would be undefined because we're not in global mode.

This is wrong. Let me simplify: use global mode like exampleHtml does — append the sketch code as a `<script>` in the body, and `new p5(undefined, container)` creates a global-mode instance inside the container. That's the same approach used in `renderSketch` in exerciseHtml.ts:

```js
var script = document.createElement('script');
script.textContent = code;
document.body.appendChild(script);
container.__p5 = new p5(undefined, container);
```

And in exampleHtml, they just inline `<script>${sketch}</script>` and `<script>${p5Source}</script>` — p5 auto-instantiates with global setup/draw.

For error handling in exampleHtml they don't catch. In renderSketch (exerciseHtml), they wrap in try/catch and show error message.

Let me rewrite fullscreenPreviewHtml to mirror renderSketch: inline p5 source, then inline a script that injects the user's code and creates the p5 instance with try/catch error display.

Actually simplest robust approach:
```html
<script>${p5Source}</script>
<script>
  // inject user code via script element so global setup/draw are defined
  var s = document.createElement('script');
  s.textContent = ${JSON.stringify(sketch)};
  document.body.appendChild(s);
</script>
<script>
  (function() {
    var container = document.getElementById('sketch');
    try {
      container.__p5 = new p5(undefined, container);
    } catch (e) {
      container.innerHTML = '<div id="error">' + ... + '</div>';
    }
  })();
</script>
```

Note: p5 auto-instantiates when it sees global setup/draw on window load (the p5 2.x source has that auto-instantiation at the end). In renderSketch they explicitly `new p5(undefined, container)` and it works because global setup/draw exist. But the auto-instantiation might ALSO fire and create a second instance at document.body... Actually in renderSketch they inject the script AFTER p5 is loaded, so p5's load-time auto-init already happened (no setup/draw then). So explicit `new p5(undefined, container)` is the only instance. Good, mirror that.

But wait — the p5 auto-init code: "window.setup&&"function"==typeof window.setup||window.draw...!ih.instance&&new ih" — it fires on window load. In renderSketch, scripts are appended dynamically; p5 source already executed before. So no auto-init from that. Good.

Let me rewrite the file cleanly.

