  return { ...state, code: state.startingCode };
  case "APPEND_CODE":
  return { ...state, code: state.code + action.text };
  case "RUN_START":
  return { ...state, isRunning: true };
  case "RUN_DONE":
  return { ...state, isRunning: false };
  case "EXERCISE_COMPLETE":
  return { ...state, completed: true };
