            </View>
            <View style={{ flexDirection: "row", gap: 6 }}>
              {["small", "medium"].map((opt) => (
                <Pressable
                  key={opt}
                  onPress={() => changeKeyboardHeight(opt)}
                  style={({ pressed }) => ({
                    paddingHorizontal: 10,
                    paddingVertical: 5,
                    borderRadius: 6,
                    minWidth: 36,
                    alignItems: "center",
